#include <vector>
#include <string>
#include <unordered_set>

class Solution {
public:
    int numUniqueEmails(std::vector<std::string>& emails) {
        std::unordered_set<std::string> unique;
        for (const auto& e : emails) {
            auto at = e.find('@');
            std::string local = e.substr(0, at);
            std::string domain = e.substr(at + 1);
            std::string cleanLocal = "";
            for (char c : local) {
                if (c == '+') break;
                if (c != '.') cleanLocal.push_back(c);
            }
            unique.insert(cleanLocal + "@" + domain);
        }
        return unique.size();
    }
};

import java.util.*;

class Solution {
    public int numUniqueEmails(String[] emails) {
        Set<String> unique = new HashSet<>();
        for (String e : emails) {
            String[] parts = e.split("@");
            String local = parts[0].split("\\+")[0].replace(".", "");
            unique.add(local + "@" + parts[1]);
        }
        return unique.size();
    }
}

function numUniqueEmails(emails) {
    const unique = new Set();
    for (const e of emails) {
        const [local, domain] = e.split('@');
        const cleanLocal = local.split('+')[0].replaceAll('.', '');
        unique.add(`${cleanLocal}@${domain}`);
    }
    return unique.size;
}
